package com.mfg.erp.controller;
import com.mfg.security.scope.ScopedQueryService;
import com.mfg.security.scope.ScopedResource;import com.mfg.common.api.ApiResponse;import com.mfg.erp.dto.SalesOrderCommand;import com.mfg.erp.entity.*;import com.mfg.erp.repo.*;import com.mfg.erp.service.SalesOrderService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/erp/sales-orders") @RequiredArgsConstructor public class SalesOrderController{private final ScopedQueryService scope;private final SalesOrderRepository repo;private final SalesOrderLineRepository lines;private final SalesOrderService service;private final com.mfg.erp.service.ErpP2Service p2Service;@GetMapping@PreAuthorize("hasAuthority('ERP:SALES_ORDER:VIEW')") public ApiResponse<Page<SalesOrder>> page(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.ok(scope.page(ScopedResource.SALES_ORDER,SalesOrder.class,page,size,null,null));}@GetMapping("/{id}")@PreAuthorize("hasAuthority('ERP:SALES_ORDER:VIEW')")public ApiResponse<Map<String,Object>> detail(@PathVariable Long id){scope.requireVisible(ScopedResource.SALES_ORDER,id);SalesOrder o=repo.findById(id).orElseThrow(()->new jakarta.persistence.EntityNotFoundException());return ApiResponse.ok(Map.of("header",o,"lines",lines.findBySalesOrderNoOrderByLineNo(o.getSalesOrderNo())));}@PostMapping@PreAuthorize("hasAuthority('ERP:SALES_ORDER:CREATE')") public ApiResponse<SalesOrder> create(@Valid @RequestBody SalesOrderCommand c){return ApiResponse.ok(service.create(c));}@PostMapping("/{id}/confirm")@PreAuthorize("hasAuthority('ERP:SALES_ORDER:CONFIRM')")public ApiResponse<SalesOrder> confirm(@PathVariable Long id){scope.requireVisible(ScopedResource.SALES_ORDER,id);p2Service.confirm(id);return ApiResponse.ok(repo.findById(id).orElseThrow());}}
